st.markdown('''<div class="top"><div class="brand"><div class="mark">◈</div>APEX / RESALE INTELLIGENCE</div><div class="status"><span class="dot"></span>MODEL ONLINE · LASSO</div></div>''', unsafe_allow_html=True)
st.markdown('''<div class="hero"><div class="kicker">01 / VEHICLE VALUATION SYSTEM</div><h1>CAR <span>RESALE</span><br>PRICE</h1><p>Configure the vehicle profile below. The visual cockpit is new; your existing FastAPI + Lasso prediction pipeline remains connected.</p></div>''', unsafe_allow_html=True)

left, right = st.columns([1.35, 1], gap="large")

with left:
    st.markdown('<div class="panel"><div class="panel-head"><div class="panel-title">Vehicle configuration</div><div class="code">INPUT / 08 PARAMS</div></div>', unsafe_allow_html=True)
    c1,c2=st.columns(2)
    with c1: age=st.slider("Vehicle age",0,15,5)
    with c2: mileage=st.slider("Mileage / km",500,220000,60000,step=500)
    m=pct(mileage,500,220000); l=max(4,m-12); r=min(96,m+12)
    st.markdown(f'<div class="bracket" style="--l:{l}%;--r:{r}%"><div class="track"></div><div class="active"></div><div class="handle hl"></div><div class="handle hr"></div><div class="bt"><span>500 KM</span><span>ACTIVE · {mileage:,} KM</span><span>220K KM</span></div></div>',unsafe_allow_html=True)
    c1,c2=st.columns(2)
    with c1: engine_cc=st.selectbox("Engine displacement / cc",[1000,1200,1500,1800,2000,2500,3000],index=2)
    with c2: owners=st.radio("Previous owners",[1,2,3,4],index=0,horizontal=True)
    c1,c2=st.columns(2)
    with c1: accident=st.radio("Accident history",[0,1],index=0,horizontal=True,format_func=lambda x:"NO" if x==0 else "YES")
    with c2: color_score=st.slider("Color popularity",1.0,10.0,5.0,step=0.1)
    c1,c2=st.columns(2)
    with c1: fuel_index=st.slider("Local fuel index",60.0,120.0,90.0,step=0.5)
    with c2: service_visits=st.slider("Service center visits",0,10,3)
    st.markdown(f'<div class="metricgrid"><div class="metric"><div class="mlabel">VEHICLE AGE</div><div class="mvalue accent">{age}Y</div></div><div class="metric"><div class="mlabel">DISTANCE</div><div class="mvalue">{mileage:,}</div></div><div class="metric"><div class="mlabel">ENGINE</div><div class="mvalue">{engine_cc}</div></div></div>',unsafe_allow_html=True)
    st.markdown('<div style="height:12px"></div>',unsafe_allow_html=True)
    predict_clicked=st.button("◈  RUN VALUATION",use_container_width=True)
    st.markdown('</div>',unsafe_allow_html=True)

with right:
    st.markdown('<div class="panel"><div class="panel-head"><div class="panel-title">2D vehicle selector</div><div class="code">HOTSPOTS / ACTIVE</div></div>',unsafe_allow_html=True)
    st.markdown('''<div class="car"><div class="caption">INTERACTIVE VEHICLE MAP / SENSOR POINTS</div><div class="body"></div><div class="window"></div><div class="wheel w1"></div><div class="wheel w2"></div><div class="hot h1"></div><div class="hot h2"></div><div class="hot h3"></div></div>''',unsafe_allow_html=True)
    dials=[("AGE",age,pct(age,0,15)),("ENGINE",engine_cc,pct(engine_cc,1000,3000)),("FUEL",f"{fuel_index:.0f}",pct(fuel_index,60,120)),("SERVICE",service_visits,pct(service_visits,0,10))]
    html='<div class="dials">'+''.join([f'<div class="dial" style="--p:{p}%"><div class="dc"><div class="dv">{v}</div><div class="dl">{lab}</div></div></div>' for lab,v,p in dials])+'</div>'
    st.markdown(html,unsafe_allow_html=True)
    st.markdown('<div style="margin-top:15px;padding:13px;border:1px solid #242c36;background:#080c11;font:7px/1.8 Space Mono;color:#69737f">HOTSPOT A · BODY CONDITION<br>HOTSPOT B · POWERTRAIN<br>HOTSPOT C · RUNNING GEAR</div></div>',unsafe_allow_html=True)

if predict_clicked:
    payload={"Age_Years":age,"Mileage_km":mileage,"Engine_CC":engine_cc,"Owner_Count":owners,"Accident_History":accident,"Color_Popularity_Score":color_score,"Local_Fuel_Price_Index":fuel_index,"Service_Center_Visits":service_visits}
    try:
        with st.spinner("Running valuation model..."):
            response=requests.post(API_URL,json=payload,timeout=30); response.raise_for_status(); predicted=response.json()["predicted_price"]
        st.markdown(f'<div class="result"><div class="rk">Estimated market resale value</div><div class="rp">{price(predicted)}</div><div class="rm">{age}Y · {mileage:,} KM · {engine_cc} CC · {owners} OWNER(S)</div></div>',unsafe_allow_html=True)
    except requests.exceptions.ConnectionError:
        st.error("Could not connect to the backend. Make sure main.py is running on port 8000.")
    except Exception as e:
        st.error(f"Something went wrong: {e}")

try:
    imp_response=requests.get(IMPORTANCE_URL,timeout=10); imp_response.raise_for_status(); importance=imp_response.json()["importance"]
    labels={"Age_Years":"Age","Mileage_km":"Mileage","Engine_CC":"Engine","Owner_Count":"Owners","Accident_History":"Accident","Color_Popularity_Score":"Color popularity","Local_Fuel_Price_Index":"Fuel index","Service_Center_Visits":"Service visits"}
    max_abs=max(abs(v) for v in importance.values()) or 1
    rows=''
    for feat,coef in importance.items():
        zero=abs(coef)<1e-6; p=0 if zero else min(100,abs(coef)/max_abs*100); rows+=f'<div class="improw"><div class="in">{labels.get(feat,feat)}</div><div class="bar"><div class="fill" style="width:{p}%"></div></div><div class="state">{"EXCLUDED" if zero else "USED"}</div></div>'
    st.markdown(f'<div class="imp"><div class="imphead"><span>MODEL INTELLIGENCE</span><span style="color:#5f6975">LASSO / FEATURE WEIGHTS</span></div>{rows}</div>',unsafe_allow_html=True)
except Exception:
    pass

st.markdown('<div class="footer">APEX RESALE INTELLIGENCE · FASTAPI · LASSO REGRESSION</div>',unsafe_allow_html=True)
